local base=raw:get(np.s(2)):view("int8"):reshape({2,3})
np.copyto(base,np.array({{1,2,3},{4,5,6}},"int8"))
local a=np.flip(base,1)
local ok,result=pcall(function()return np.cumprod(a)end)
assert(ok==true,"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: acceptance"..": "..tostring(result))
eq(np.astype(result,"U40"):tolist(),{"4","20","120","120","240","720"},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: result: integer strings")
eq(result.shape,{6},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: result: shape")
eq(result.strides,{8},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: result: strides")
eq(result.dtype,"int64","unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: result: dtype")
eq(a:tolist(),{{4,5,6},{1,2,3}},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: input state: values")
eq(a.shape,{2,3},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: input state: shape")
eq(a.strides,{-3,1},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: input state: strides")
eq(a.dtype,"int8","unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: input state: dtype")
eq(base:tolist(),{{1,2,3},{4,5,6}},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: base state: values")
eq(base.shape,{2,3},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: base state: shape")
eq(base.strides,{3,1},"unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: base state: strides")
eq(base.dtype,"int8","unaligned/int8(2, 3)/reverse_first/cumprod/offset1/outFalse: base state: dtype")
cases=cases+1
end
