local base=raw:get(np.s(2)):view("uint8"):reshape({2,3})
np.copyto(base,np.array({{1,2,3},{4,5,6}},"uint8"))
local a=np.transpose(base)
local ok,result=pcall(function()return np.prod(a,{keepdims=true})end)
assert(ok==true,"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: acceptance"..": "..tostring(result))
eq(np.astype(result,"U40"):tolist(),{{"720"}},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: result: integer strings")
eq(result.shape,{1,1},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: result: shape")
eq(result.strides,{8,8},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: result: strides")
eq(result.dtype,"uint64","unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: result: dtype")
eq(a:tolist(),{{1,4},{2,5},{3,6}},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: input state: values")
eq(a.shape,{3,2},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: input state: shape")
eq(a.strides,{1,3},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: input state: strides")
eq(a.dtype,"uint8","unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: input state: dtype")
eq(base:tolist(),{{1,2,3},{4,5,6}},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: base state: values")
eq(base.shape,{2,3},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: base state: shape")
eq(base.strides,{3,1},"unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: base state: strides")
eq(base.dtype,"uint8","unaligned/uint8(3, 2)/transpose/prod/offset1/outFalse: base state: dtype")
cases=cases+1
end
