local base=raw:get(np.s(2)):view("uint8"):reshape({2,3})
np.copyto(base,np.array({{1,2,3},{4,5,6}},"uint8"))
local a=np.flip(base,1)
local ok,result=pcall(function()return np.add(a,a)end)
assert(ok==true,"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: acceptance"..": "..tostring(result))
eq(result:tolist(),{{8,10,12},{2,4,6}},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: result: values")
eq(result.shape,{2,3},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: result: shape")
eq(result.strides,{3,1},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: result: strides")
eq(result.dtype,"uint8","unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: result: dtype")
eq(a:tolist(),{{4,5,6},{1,2,3}},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: input state: values")
eq(a.shape,{2,3},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: input state: shape")
eq(a.strides,{-3,1},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: input state: strides")
eq(a.dtype,"uint8","unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: input state: dtype")
eq(base:tolist(),{{1,2,3},{4,5,6}},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: base state: values")
eq(base.shape,{2,3},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: base state: shape")
eq(base.strides,{3,1},"unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: base state: strides")
eq(base.dtype,"uint8","unaligned/uint8(2, 3)/reverse_first/add/offset1/outFalse: base state: dtype")
cases=cases+1
end
