local base=raw:get(np.s(2)):view("uint32"):reshape({2,3})
np.copyto(base,np.array({{1,2,3},{4,5,6}},"uint32"))
local a=np.flip(base,1)
local ok,result=pcall(function()return np.prod(a,{keepdims=true})end)
assert(ok==true,"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: acceptance"..": "..tostring(result))
eq(np.astype(result,"U40"):tolist(),{{"720"}},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: result: integer strings")
eq(result.shape,{1,1},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: result: shape")
eq(result.strides,{8,8},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: result: strides")
eq(result.dtype,"uint64","unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: result: dtype")
eq(a:tolist(),{{4,5,6},{1,2,3}},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: input state: values")
eq(a.shape,{2,3},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: input state: shape")
eq(a.strides,{-12,4},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: input state: strides")
eq(a.dtype,"uint32","unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: input state: dtype")
eq(base:tolist(),{{1,2,3},{4,5,6}},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: base state: values")
eq(base.shape,{2,3},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: base state: shape")
eq(base.strides,{12,4},"unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: base state: strides")
eq(base.dtype,"uint32","unaligned/uint32(2, 3)/reverse_first/prod/offset1/outFalse: base state: dtype")
cases=cases+1
end
