np.copyto(base,np.array({{np.complex(0.25,0.0),np.complex(0.5,0.0),np.complex(0.75,0.0)},{np.complex(1.0,0.0),np.complex(1.25,0.0),np.complex(1.5,0.0)}},"complex256"))
local a=base
local out_raw=np.zeros({a.nbytes+1},"uint8")
local out=out_raw:get(np.s(2)):view(a.dtype):reshape(a.shape)
local ok,result=pcall(function()return np.minimum(a,a,{out=out})end)
assert(ok==true,"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: acceptance"..": "..tostring(result))
eq(result:tolist(),{{np.complex(0.25,0.0),np.complex(0.5,0.0),np.complex(0.75,0.0)},{np.complex(1.0,0.0),np.complex(1.25,0.0),np.complex(1.5,0.0)}},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: result: values")
eq(result.shape,{2,3},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: result: shape")
