eq(out:tolist(),{{np.complex(0.25,0.0),np.complex(0.5,0.0),np.complex(0.75,0.0)},{np.complex(1.0,0.0),np.complex(1.25,0.0),np.complex(1.5,0.0)}},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: output state: values")
eq(out.shape,{2,3},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: output state: shape")
eq(out.strides,{96,32},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: output state: strides")
eq(out.dtype,"complex256","unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: output state: dtype")
eq(a:tolist(),{{np.complex(0.25,0.0),np.complex(0.5,0.0),np.complex(0.75,0.0)},{np.complex(1.0,0.0),np.complex(1.25,0.0),np.complex(1.5,0.0)}},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: input state: values")
eq(a.shape,{2,3},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: input state: shape")
eq(a.strides,{96,32},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: input state: strides")
eq(a.dtype,"complex256","unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: input state: dtype")
eq(base:tolist(),{{np.complex(0.25,0.0),np.complex(0.5,0.0),np.complex(0.75,0.0)},{np.complex(1.0,0.0),np.complex(1.25,0.0),np.complex(1.5,0.0)}},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: base state: values")
eq(base.shape,{2,3},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: base state: shape")
eq(base.strides,{96,32},"unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: base state: strides")
eq(base.dtype,"complex256","unaligned/complex256(2, 3)/base/minimum/offset3/outTrue: base state: dtype")
cases=cases+1
end
